pay.quantity:
sum(
  leave.rows.filter(r, r.can_encash && r.activity == "ENCASHMENT").map(
    r,
    r.days
  )
)

sum(
  leave.rows.filter(r, r.is_npl && r.activity == "TIME_OFF").map(
    r,
    r.days
  )
)

sum(
  leave.rows.filter(
    r,
    r.code == "SUSPENSION_PENDING_DISCIPLINE"
    &&r.activity == "TIME_OFF"
  ).map(
    r,
    r.days
  )
)
